using System.Net;
using System.Net.Http.Json;
using sv_c9ceb80fda6f4d53b0609bd29e651fd4.Client.Models;

namespace sv_c9ceb80fda6f4d53b0609bd29e651fd4.Client.Services;

public sealed class ClientShipmentService(HttpClient http) : IShipmentService
{
    public async Task<Shipment?> GetShipmentAsync(string trackingNumber, CancellationToken ct)
    {
        var encodedTrackingNumber = Uri.EscapeDataString(trackingNumber);
        var response = await http.GetAsync($"api/shipments/{encodedTrackingNumber}", ct);

        if (response.StatusCode == HttpStatusCode.NotFound)
        {
            return null;
        }

        response.EnsureSuccessStatusCode();
        return await response.Content.ReadFromJsonAsync<Shipment>(ct);
    }
}

